// Checkout page logic.
interface Cart {
  items: number[];
}

function total(cart: Cart): number {
  return cart.items.reduce((a, b) => a + b, 0);
}

export function chargeCard(cart: Cart | undefined): number {
  const amount = total(cart as Cart);
  if (amount > 100) {
    throw new Error('card declined');
  }
  return amount;
}

export function checkout(): number {
  return chargeCard(undefined);
}
